import{_ as a,o as e,c as s,a2 as i}from"./chunks/framework.ORnkkB96.js";const k=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"en/instalacao.md","filePath":"en/instalacao.md","lastUpdated":1792519643000}'),n={name:"en/instalacao.md"};function r(o,t,l,d,h,p){return e(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Vision.AI runs containerized with <strong>Docker Swarm</strong>. The official installer downloads the right version, unpacks it and brings up all fifteen services at once.</p><blockquote><p>The full guide, per operating system, lives in the installer repository: <strong><a href="https://github.com/bortolottic/vision.ai.installer" target="_blank" rel="noreferrer">vision.ai.installer</a></strong>. This page is the summary.</p></blockquote><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Minimum</th><th>Recommended</th></tr></thead><tbody><tr><td>RAM</td><td>8 GB</td><td>16 GB</td></tr><tr><td>CPU</td><td>4 cores</td><td>8 cores</td></tr><tr><td>Disk</td><td>40 GB free</td><td>100 GB free</td></tr></tbody></table><p>Inference and training run on <strong>CPU</strong> by default. For real time with several cameras, use a node with an <strong>NVIDIA GPU</strong> and the <code>--gpu</code> mode (see <a href="/vision.ai.installer/en/operacao#gpu">Operations</a>).</p><h2 id="ports" tabindex="-1">Ports <a class="header-anchor" href="#ports" aria-label="Permalink to &quot;Ports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Port</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>9080</strong></td><td>The platform in the browser</td></tr><tr><td>8189/UDP</td><td>WebRTC (live video)</td></tr><tr><td>3433</td><td>Database (inspection only; can be closed)</td></tr><tr><td>443</td><td>HTTPS, in <code>--ssl</code> mode</td></tr></tbody></table><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li>Install Docker and enable Swarm:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swarm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div></li><li>Run the installer:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/bortolottic/vision.ai.installer/refs/heads/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div></li><li>Open <code>http://localhost:9080</code> (or the server address on port 9080).</li></ol><p>For a specific version, append the tag:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/bortolottic/vision.ai.installer/refs/heads/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> V1.0.0.0</span></span></code></pre></div><h2 id="after-installing" tabindex="-1">After installing <a class="header-anchor" href="#after-installing" aria-label="Permalink to &quot;After installing&quot;">​</a></h2><ul><li><strong>Secrets:</strong> generated automatically on the first install and written to <code>/tmp/vision-ai/vision-ai/.env.production</code>. <strong>Back up that file.</strong></li><li><strong>Public address:</strong> on a server, set <code>VISION_PUBLIC_URL</code> and <code>VISION_WEBRTC_HOST</code> in <code>.env.production</code> and run <code>./deploy_production.sh</code> again.</li></ul><p>GPU, HTTPS and backup details are in <a href="/vision.ai.installer/en/operacao">Operations</a>.</p>',15)])])}const g=a(n,[["render",r]]);export{k as __pageData,g as default};
